// Oracle-only stand-in for the npm `cross-spawn` package: forwards to node's
// child_process so the real upstream `child-process.ts` behaves natively.
import { spawn as nodeSpawn, spawnSync as nodeSpawnSync } from "node:child_process";

function parse(command, args, options) {
  let file = command;
  let rest = args ?? [];
  let opts = options ?? {};
  if (rest !== null && !Array.isArray(rest) && typeof rest === "object") {
    opts = rest;
    rest = [];
  }
  return { file, rest, opts };
}

export default function crossSpawn(command, args, options) {
  const { file, rest, opts } = parse(command, args, options);
  return nodeSpawn(file, rest, opts);
}
crossSpawn.spawn = crossSpawn;
crossSpawn.sync = (command, args, options) => {
  const { file, rest, opts } = parse(command, args, options);
  return nodeSpawnSync(file, rest, opts);
};

export function spawn(command, args, options) {
  const { file, rest, opts } = parse(command, args, options);
  return nodeSpawn(file, rest, opts);
}
export function sync(command, args, options) {
  const { file, rest, opts } = parse(command, args, options);
  return nodeSpawnSync(file, rest, opts);
}
